fn bitwise_and(x1: &Vec<u8>, x2: &Vec<u8>) -> Vec<u8> {
    assert_eq!(x1.len(), x2.len(), "inputs must have the same length");

    let mut out = Vec::with_capacity(x1.len());
    for i in 0..x1.len() {
        let a = x1[i];
        let b = x2[i];
        let c = a & b;

        // Required properties (checked for every valid index):
        debug_assert_eq!(c, a & b); // definition
        debug_assert_eq!(a & b, b & a); // commutative
        debug_assert_eq!(a & 0u8, 0u8); // AND with zero yields zero
        debug_assert_eq!(a & a, a); // idempotent
        debug_assert!(c <= a); // result <= each operand
        debug_assert!(c <= b);

        out.push(c);
    }
    out
}